Method.Source:
/// <summary>
/// Inserts data into <c>METTMSEngineProcessingTmp</c>.
/// </summary>
/// <param name = "_tmsEngineProcessingTmp"><c>METTMSEngineProcessingTmp</c>.</param>
/// <param name = "_query"><c>Query</c>.</param>
static void insertDataFromQuery(METTMSEngineProcessingTmp _tmsEngineProcessingTmp, Query _query)
{
    METTMSProcessingStatus tmsProcessingStatus;
    QueryBuildFieldList    qfl;
    QueryBuildDatasource   qbds;
    Map                    fieldList;

    qbds = _query.dataSourceTable(tableNum(METTMSProcessingStatus));

    qfl = qbds.fields();

    qfl.clearFieldList();
    qfl.addField(fieldNum(METTMSProcessingStatus, DocumentNumber));
    qfl.addField(fieldNum(METTMSProcessingStatus, OrderType));
    qfl.addField(fieldNum(METTMSProcessingStatus, ExecutionMode));

    fieldList = new Map(Types::String, Types::Container);

    fieldList.insert(fieldStr(METTMSEngineProcessingTmp, DocumentNumber), [qbds.uniqueId(), fieldStr(METTMSProcessingStatus, DocumentNumber)]);
    fieldList.insert(fieldStr(METTMSEngineProcessingTmp, OrderType), [qbds.uniqueId(), fieldStr(METTMSProcessingStatus, OrderType)]);
    fieldList.insert(fieldStr(METTMSEngineProcessingTmp, ExecutionMode), [qbds.uniqueId(), fieldStr(METTMSProcessingStatus, ExecutionMode)]);

    Query::insert_recordset(_tmsEngineProcessingTmp, fieldList, _query);

    update_recordset _tmsEngineProcessingTmp
        setting TMSEngineProcessingStatusDateTime = tmsProcessingStatus.CreatedDateTime
            join tmsProcessingStatus
                where _tmsEngineProcessingTmp.DocumentNumber == tmsProcessingStatus.DocumentNumber
                &&    _tmsEngineProcessingTmp.ExecutionMode == tmsProcessingStatus.ExecutionMode
                &&    _tmsEngineProcessingTmp.OrderType == tmsProcessingStatus.OrderType;
}
